import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.DiAOIirN.js";var i=JSON.parse(`{"title":"Environment variables","description":"","frontmatter":{},"headers":[],"relativePath":"reference/environment.md","filePath":"reference/environment.md","lastUpdated":1788465684000}`),a={name:`reference/environment.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to “Environment variables”">​</a></h1><p>Every one of these is read once at startup. <code>SMTP_PASSWORD</code> is deleted from the process environment as soon as it has been read, before any other branch runs, so it is not visible to child processes or in <code>/proc/&lt;pid&gt;/environ</code>.</p><p>The server starts without credentials on purpose: it completes the MCP handshake and answers <code>tools/list</code> so that registries and sandbox inspectors can introspect it. Every call then fails with setup instructions instead of reaching a server.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>SMTP_HOST</code></td><td>yes</td><td><code>string</code></td><td>Hostname of the SMTP server, e.g. smtp.example.net.</td></tr><tr><td><code>SMTP_PORT</code></td><td>no</td><td><code>number</code></td><td>Port. Defaults to 587 for starttls, 465 for implicit, 25 for none.</td></tr><tr><td><code>SMTP_TLS</code></td><td>no</td><td><code>string</code></td><td>starttls (default), implicit or none. STARTTLS is required, never opportunistic.</td></tr><tr><td><code>SMTP_USER</code></td><td>yes</td><td><code>string</code></td><td>Username for SMTP authentication.</td></tr><tr><td><code>SMTP_PASSWORD</code></td><td>yes</td><td><code>string</code></td><td>Password or app-specific password for SMTP authentication.</td></tr><tr><td><code>SMTP_FROM</code></td><td>yes</td><td><code>string</code></td><td>The only sender this server will use, e.g. &quot;Name &lt;person@example.net&gt;&quot;. There is no from parameter.</td></tr><tr><td><code>SMTP_ALLOW_SEND</code></td><td>no</td><td><code>boolean</code></td><td>Set to &quot;true&quot; to register the sending tools. Defaults to false: the server cannot send until it is set.</td></tr><tr><td><code>SMTP_ALLOWED_RECIPIENTS</code></td><td>no</td><td><code>string</code></td><td>Comma-separated addresses and @domains this server may write to. Required with SMTP_ALLOW_SEND=true; &quot;*&quot; allows any.</td></tr><tr><td><code>SMTP_MAX_RECIPIENTS</code></td><td>no</td><td><code>number</code></td><td>Maximum distinct recipients across To, Cc and Bcc in one message. Default 10.</td></tr><tr><td><code>SMTP_MAX_SENDS_PER_HOUR</code></td><td>no</td><td><code>number</code></td><td>Sliding hourly cap on messages sent. Default 20.</td></tr><tr><td><code>SMTP_MAX_MESSAGE_BYTES</code></td><td>no</td><td><code>number</code></td><td>Maximum size of the composed message. Default 10485760.</td></tr><tr><td><code>SMTP_MAX_ATTACHMENT_BYTES</code></td><td>no</td><td><code>number</code></td><td>Maximum size of a single attachment. Default 5242880.</td></tr><tr><td><code>SMTP_ATTACHMENT_DIR</code></td><td>no</td><td><code>string</code></td><td>Directory attachments are read from. Unset means attachments are unavailable.</td></tr><tr><td><code>SMTP_ATTACHMENT_TYPES</code></td><td>no</td><td><code>string</code></td><td>Comma-separated content types that may be attached. Defaults to a document and image allowlist; <code>text/html</code> and <code>application/zip</code> are opt-in.</td></tr><tr><td><code>SMTP_SIGNATURE</code></td><td>no</td><td><code>string</code></td><td>Text appended below the standard signature delimiter of every message.</td></tr><tr><td><code>SMTP_AUDIT_LOG</code></td><td>no</td><td><code>string</code></td><td>File the audit lines are appended to, in addition to stderr.</td></tr><tr><td><code>SMTP_ALLOW_TOOLS</code></td><td>no</td><td><code>string</code></td><td>Comma-separated tool names, a prefix with one trailing *, or &quot;essential&quot; for the curated preset.</td></tr><tr><td><code>SMTP_DENY_TOOLS</code></td><td>no</td><td><code>string</code></td><td>Comma-separated tool names or prefixes to remove, applied after SMTP_ALLOW_TOOLS.</td></tr><tr><td><code>SMTP_INSECURE_TLS</code></td><td>no</td><td><code>boolean</code></td><td>Set to &quot;true&quot; to accept self-signed certificates. Prefer a proper internal CA.</td></tr><tr><td><code>ELICITATION</code></td><td>no</td><td><code>boolean</code></td><td><code>false</code> replaces the approval dialog with the two-call token. Default <code>true</code>. <strong>Not prefixed.</strong></td></tr></tbody></table><h2 id="the-two-that-differ-from-the-rest-of-the-family" tabindex="-1">The two that differ from the rest of the family <a class="header-anchor" href="#the-two-that-differ-from-the-rest-of-the-family" aria-label="Permalink to “The two that differ from the rest of the family”">​</a></h2><p><strong><code>SMTP_ALLOW_SEND</code> defaults to false.</strong> The read/write variables in the sibling servers guard changes to a system the operator already owns; this one guards a channel out of it. A freshly installed smtp-mcp that could send on the first tool call would be a server whose worst day happens before anybody has read its README. It accepts exactly the string <code>true</code>.</p><p><strong>An unset <code>SMTP_ALLOWED_RECIPIENTS</code> is a startup error, not &quot;anyone&quot;.</strong> Treating a missing line as permission is how an oversight becomes a delivered message. Write <code>*</code> if you mean it.</p><h2 id="values-that-stop-the-server" tabindex="-1">Values that stop the server <a class="header-anchor" href="#values-that-stop-the-server" aria-label="Permalink to “Values that stop the server”">​</a></h2><p>Malformed configuration exits rather than being ignored, because the alternative is a server that looks like it is running and is not doing what its operator believes:</p><ul><li>a host carrying a scheme, a port, credentials or a line break</li><li>a port outside 1–65535, or a non-positive limit</li><li>an <code>SMTP_TLS</code> value other than <code>starttls</code>, <code>implicit</code> or <code>none</code></li><li>an <code>SMTP_FROM</code> that is not an email address</li><li>an entry in <code>SMTP_ALLOWED_RECIPIENTS</code> that is neither an address nor an <code>@domain</code></li><li><code>SMTP_ALLOW_SEND=true</code> with no allowlist</li><li>a tool name in <code>SMTP_ALLOW_TOOLS</code> or <code>SMTP_DENY_TOOLS</code> that matches nothing</li></ul><p>Error messages never echo the offending value. Configuration errors end up in logs, and the &quot;not a valid port&quot; branch is precisely where a token pasted into the wrong variable arrives.</p><h2 id="elicitation" tabindex="-1"><code>ELICITATION</code> <a class="header-anchor" href="#elicitation" aria-label="Permalink to “ELICITATION”">​</a></h2><p>Whether a client that <em>can</em> show a dialog is asked before <code>send_mail</code>, <code>reply_mail</code> or <code>forward_mail</code> acts. Default <code>true</code>. <code>false</code> takes the two-call-token path instead — it does not remove the guard, and a server started with it off prints one line saying so.</p><p>Two ways it differs from every other variable here:</p><ul><li><strong>No prefix.</strong> One <code>export ELICITATION=false</code> reaches every MCP server in the same environment, not just this one. That is the point of it and also its risk, and this is the server where it costs the most: every send asks. See <a href="/guide/approval">Asking a person</a>.</li><li><strong>Fatal on anything else.</strong> Like <code>SMTP_TLS</code>, and unlike <code>SMTP_ALLOW_SEND</code>: <code>1</code>, <code>off</code> or a typo stop the server with exit code 1. It is the only variable here that defaults to <em>on</em>, and a typo that fell back would leave the dialog running while you believed it was off.</li></ul><p>Values are trimmed and matched case-insensitively. It is read <em>after</em> <code>SMTP_PASSWORD</code> is deleted from <code>process.env</code>, so the fatal path cannot leave the password sitting there for a crash reporter.</p>`,16)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};